"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import asyncio
import copy
import html
import json
import logging
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


# ---------------------------------------------------------------------------
# Built-in tool dispatch
# ---------------------------------------------------------------------------


def _serialize_assistant(msg) -> dict:
    """Convert an LLM response Message into a plain dict for the next request.

    Preserves `reasoning_content` for models that require it on tool round-trips. Strips
    fields the API rejects on input (`refusal`, `audio`, etc.)."""
    if hasattr(msg, "model_dump"):
        d = msg.model_dump(exclude_none=True)
    elif hasattr(msg, "dict"):
        d = msg.dict(exclude_none=True)
    else:
        d = {"role": getattr(msg, "role", "assistant")}
        if getattr(msg, "content", None) is not None:
            d["content"] = msg.content
        if getattr(msg, "reasoning_content", None) is not None:
            d["reasoning_content"] = msg.reasoning_content
        tcs = getattr(msg, "tool_calls", None)
        if tcs:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": getattr(tc, "type", "function"),
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                for tc in tcs
            ]
    if "tool_calls" in d and "content" not in d:
        d["content"] = ""
    for k in (
        "function_call",
        "audio",
        "annotations",
        "refusal",
        "provider_specific_fields",
    ):
        d.pop(k, None)
    return d


def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _make_chat_tool_call(call_id: str, name: str, arguments: str):
    """Create a chat-completions-shaped tool call object."""
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(name=name, arguments=arguments),
    )


def _responses_call_to_chat_tool_call(fc: Any):
    call_id = (
        _obj_get(fc, "call_id")
        or _obj_get(fc, "id")
        or _obj_get(fc, "tool_call_id")
        or ""
    )
    name = _obj_get(fc, "name") or _obj_get(_obj_get(fc, "function", {}), "name") or ""
    arguments = (
        _obj_get(fc, "arguments")
        or _obj_get(_obj_get(fc, "function", {}), "arguments")
        or "{}"
    )
    if not isinstance(arguments, str):
        arguments = json.dumps(arguments, ensure_ascii=False)
    return _make_chat_tool_call(call_id, name, arguments)


def _chat_tool_call_to_common(tc: Any, *, injected: bool = False) -> dict:
    fn = _obj_get(tc, "function", {}) or {}
    args = _obj_get(fn, "arguments", "{}") or "{}"
    if not isinstance(args, str):
        args = json.dumps(args, ensure_ascii=False)
    out = {
        "id": _obj_get(tc, "id", "") or "",
        "name": _obj_get(fn, "name", "") or "",
        "arguments": args,
    }
    if injected:
        out["injected"] = True
    return out

# ---------------------------------------------------------------------------
# Final-answer gate helpers
# ---------------------------------------------------------------------------

_SHORT_ANSWER_MAX_WORDS = 12

_LEADING_ANSWER_QUALIFIERS_RE = re.compile(
    r"^(?:(?:the|my|our)\s+)?(?:final\s+)?(?:answer|result|response)\b\s*"
    r"(?:to\s+the\s+question\s*)?(?:is|:)?\s*",
    re.IGNORECASE,
)
_ANSWER_COLON_RE = re.compile(r"^answer\s*:\s*", re.IGNORECASE)
_IT_IS_RE = re.compile(r"^(?:it|this|that)\s+is\s*", re.IGNORECASE)
_ITS_RE = re.compile(r"^it's\s*", re.IGNORECASE)
_I_THINK_RE = re.compile(
    r"^(?:i\s+)?(?:think|believe|would\s+say)\s+(?:that\s+)?", re.IGNORECASE
)
_BASED_ON_RE = re.compile(
    r"^(?:based\s+on|according\s+to)\s+[^,.]{0,120}[,.]\s*", re.IGNORECASE
)
_BASED_ON_PREFIX_RE = re.compile(r"^(?:based\s+on|according\s+to)\b", re.IGNORECASE)
_TRAILING_HEDGE_RE = re.compile(
    r"\s*[,;]\s*(?:i\s+think|i\s+believe|probably|likely|possibly|maybe|"
    r"not\s+sure|uncertain)\s*\.?\s*$",
    re.IGNORECASE,
)
_HEDGING_RE = re.compile(
    r"\b(?:I\s+think|I\s+believe|likely|probably|possibly|maybe|perhaps|"
    r"might\s+be|may\s+be|it\s+appears|it\s+seems|appears\s+to\s+be|"
    r"seems\s+to\s+be|not\s+sure|uncertain|to\s+the\s+best\s+of\s+my\s+knowledge|"
    r"the\s+evidence\s+suggests|I\s+would\s+say)\b",
    re.IGNORECASE,
)
_PARENTHETICAL_QUALIFIER_RE = re.compile(
    r"\([^)]*\b(?:probably|likely|possibly|maybe|perhaps|not\s+sure|uncertain|"
    r"I\s+think|I\s+believe|based\s+on|according\s+to|it\s+seems)\b[^)]*\)",
    re.IGNORECASE,
)
_LEADING_PARENTHETICAL_QUALIFIER_RE = re.compile(
    r"^\s*\([^)]*\b(?:probably|likely|possibly|maybe|perhaps|not\s+sure|uncertain|"
    r"I\s+think|I\s+believe|based\s+on|according\s+to|it\s+seems)\b[^)]*\)\s*[,:]?\s*",
    re.IGNORECASE,
)
_TRAILING_PARENTHETICAL_QUALIFIER_RE = re.compile(
    r"\s*[,;]?\s*\([^)]*\b(?:probably|likely|possibly|maybe|perhaps|not\s+sure|uncertain|"
    r"I\s+think|I\s+believe|based\s+on|according\s+to|it\s+seems)\b[^)]*\)\s*\.?\s*$",
    re.IGNORECASE,
)
_SENTENCE_START_RE = re.compile(r"^(?:The|This|That|It|There|Here|A|An)\b", re.IGNORECASE)
_SENTENCE_END_RE = re.compile(r"[.!?]\s*$")
_VERB_SENTENCE_RE = re.compile(
    r"\b(?:is|are|was|were|has|have|had|means|refers\s+to|located\s+in|"
    r"born\s+in|died\s+in|founded\s+in)\b",
    re.IGNORECASE,
)

_RAW_TOOL_TAG_RE = re.compile(r"<\s*(/?)\s*([^\s>]+)([^>]*)>", re.DOTALL)
_RAW_TOOL_BLOCK_TAGS = {"invoke", "tool_call", "function_call"}
_RAW_PARAM_TAGS = {"parameter", "param", "arg", "argument", "name", "arguments", "input"}
_RAW_TOOL_MARKUP_RE = re.compile(
    r"<\s*(?:｜{1,2}DSML｜{1,2})?(?:tool_calls|invoke|tool_call|function_calls?)\b",
    re.IGNORECASE,
)


def _strip_markdown_wrappers(text: str) -> str:
    """Remove markdown fences, bullets, emphasis, and em-dash wrappers."""
    t = (text or "").strip()
    if not t:
        return ""
    if t.startswith("```"):
        t = re.sub(r"^```[^\n]*\n?", "", t).strip()
        t = re.sub(r"\n?```$", "", t).strip()
    t = re.sub(r"^\s*(?:[-*]|\d+[.)])\s+", "", t).strip()
    t = re.sub(r"^\s*>\s*", "", t).strip()
    t = t.strip(' \t\r\n"\'`*_~')
    t = re.sub(r"^[—–]\s*", "", t).strip()
    t = re.sub(r"\s*[—–]$", "", t).strip()
    if (
        len(t) >= 2
        and t.startswith("(")
        and t.endswith(")")
        and "(" not in t[1:-1]
        and ")" not in t[1:-1]
    ):
        inner = t[1:-1].strip()
        if inner:
            t = inner
    return t


def _has_answer_scaffolding(text: str) -> bool:
    t = _strip_markdown_wrappers(text)
    return bool(
        _LEADING_ANSWER_QUALIFIERS_RE.match(t)
        or _ANSWER_COLON_RE.match(t)
        or _IT_IS_RE.match(t)
        or _ITS_RE.match(t)
        or _I_THINK_RE.match(t)
        or _BASED_ON_RE.match(t)
        or _BASED_ON_PREFIX_RE.match(t)
    )


def _looks_like_full_sentence(text: str) -> bool:
    t = _strip_markdown_wrappers(text)
    words = len(re.findall(r"\S+", t))
    if words < 4:
        return False
    if _SENTENCE_START_RE.match(t) and _SENTENCE_END_RE.search(t):
        return True
    if words >= 6 and _VERB_SENTENCE_RE.search(t):
        return True
    return False


def _is_short_answer(text: str) -> bool:
    """True when `text` is already a terse answer phrase.

    The runtime should leave such answers untouched so successful one-shot
    answers are not perturbed by the extraction gate.
    """
    t = _strip_markdown_wrappers(text)
    if not t:
        return True
    words = len(re.findall(r"\S+", t))
    if words > _SHORT_ANSWER_MAX_WORDS:
        return False
    if _has_answer_scaffolding(t):
        return False
    if _HEDGING_RE.search(t):
        return False
    if _PARENTHETICAL_QUALIFIER_RE.search(t):
        return False
    if _looks_like_full_sentence(t):
        return False
    return True


def _strip_final_sentence_period(text: str) -> str:
    """Remove one sentence-ending period unless it belongs to an abbreviation."""
    if not text.endswith(".") or len(text) <= 2:
        return text
    if "." in text[:-1]:
        return text
    if re.match(r"^(?:etc|vs|mr|mrs|ms|dr|prof|st|jr|sr)\.$", text, re.IGNORECASE):
        return text
    return text[:-1]


def _strip_answer_scaffolding(text: str) -> str:
    """Deterministic fallback: strip qualifiers and sentence scaffolding."""
    t = _strip_markdown_wrappers(text)
    if not t:
        return text.strip()
    t = _LEADING_ANSWER_QUALIFIERS_RE.sub("", t).strip()
    t = _ANSWER_COLON_RE.sub("", t).strip()
    t = _IT_IS_RE.sub("", t).strip()
    t = _ITS_RE.sub("", t).strip()
    t = _I_THINK_RE.sub("", t).strip()
    t = _BASED_ON_RE.sub("", t).strip()
    t = _LEADING_PARENTHETICAL_QUALIFIER_RE.sub("", t).strip()
    t = _TRAILING_PARENTHETICAL_QUALIFIER_RE.sub("", t).strip()
    t = _TRAILING_HEDGE_RE.sub("", t).strip()
    t = re.sub(r"\s*[—–]\s*$", "", t).strip()
    t = _strip_final_sentence_period(t).strip()
    return t


_ANSWER_EXTRACTION_TEMPLATE = """You are an answer extractor. Given an original question and a draft answer, return only the shortest exact answer. Preserve exact names, numbers, dates, URLs, and any punctuation that is part of the answer. Do not add explanation, hedging, citations, markdown formatting, or phrases such as "the answer is". If the draft answer is already a short exact answer phrase, return it unchanged.

Question: {question}

Draft answer:
{draft}

Short answer:"""


async def _extract_short_answer(candidate: str, ctx: Context) -> str | None:
    prompt = _ANSWER_EXTRACTION_TEMPLATE.format(question=ctx.question, draft=candidate)
    extracted = await ctx.side_text(
        prompt, purpose="final_answer_gate", max_tokens=160
    )
    if not extracted:
        return None
    return _strip_answer_scaffolding(extracted)


async def _gate_final_answer(candidate: str, ctx: Context) -> str:
    """Extract a terse answer from an over-verbose or qualified candidate."""
    candidate = (candidate or "").strip()
    if not candidate or _is_short_answer(candidate):
        return candidate
    extracted = await _extract_short_answer(candidate, ctx)
    if extracted and extracted != candidate:
        if _is_short_answer(extracted) or len(extracted) < len(candidate):
            return extracted
    stripped = _strip_answer_scaffolding(candidate)
    if stripped and stripped != candidate:
        return stripped
    return candidate


# ---------------------------------------------------------------------------
# Raw DSML/XML tool-call parsing
# ---------------------------------------------------------------------------


def _normalize_raw_tag_name(name: str) -> str:
    name = (name or "").strip().lstrip("/")
    name = re.sub(r"｜{1,2}DSML｜{1,2}", "", name)
    name = name.replace("｜", "").replace("DSML", "")
    return name.strip().lower()


def _xml_unescape(value: str) -> str:
    return html.unescape(value or "")


def _parse_raw_attrs(attr_text: str) -> dict:
    attrs: dict = {}
    for key, _quote, value in re.findall(
        r"([A-Za-z_:][\w:.-]*)\s*=\s*([\"'])(.*?)\2",
        attr_text or "",
        re.DOTALL,
    ):
        attrs[key.lower()] = _xml_unescape(value)
    return attrs


def _iter_raw_blocks(text: str, tags: set[str]):
    """Yield (open_tag, body, start, end) for recognized XML-style blocks."""
    stack: list[dict] = []
    for m in _RAW_TOOL_TAG_RE.finditer(text or ""):
        raw = m.group(0)
        is_close = bool(m.group(1))
        name = _normalize_raw_tag_name(m.group(2))
        if name not in tags:
            continue
        attrs = _parse_raw_attrs(m.group(3))
        self_closing = raw.rstrip().endswith("/>")
        if is_close:
            if not stack:
                continue
            open_idx = None
            for j in range(len(stack) - 1, -1, -1):
                if stack[j]["name"] == name:
                    open_idx = j
                    break
            if open_idx is None:
                continue
            open_item = stack.pop(open_idx)
            yield open_item, text[open_item["body_start"]:m.start()], open_item["start"], m.end()
        elif self_closing:
            yield {"name": name, "attrs": attrs}, None, m.start(), m.end()
        else:
            stack.append(
                {
                    "name": name,
                    "attrs": attrs,
                    "body_start": m.end(),
                    "start": m.start(),
                }
            )


def _raw_body_text(body: str | None) -> str:
    if not body:
        return ""
    text = _RAW_TOOL_TAG_RE.sub("", body)
    return _xml_unescape(text).strip()


def _parse_raw_child_tags(body: str | None) -> dict:
    out: dict = {}
    for open_tag, child_body, _start, _end in _iter_raw_blocks(body or "", _RAW_PARAM_TAGS):
        key = (open_tag["attrs"].get("name") or open_tag["name"]).lower()
        value = _raw_body_text(child_body)
        if key == "name":
            out["name"] = value
        elif key in {"arguments", "args", "parameters", "json", "input"}:
            out.setdefault("arguments", value)
        else:
            out[key] = value
    return out


def _coerce_json_object(value: Any) -> dict:
    if isinstance(value, dict):
        return dict(value)
    if not isinstance(value, str):
        return {}
    text = value.strip()
    if not text:
        return {}
    try:
        parsed = json.loads(text)
    except Exception:
        return {}
    return parsed if isinstance(parsed, dict) else {}


def _extract_raw_tool_calls(text: str, ctx: Context) -> list[dict]:
    """Parse recognized tool invocations from raw DSML/XML assistant text."""
    if not text:
        return []
    calls: list[dict] = []
    for idx, (open_tag, body, _start, _end) in enumerate(
        _iter_raw_blocks(text, _RAW_TOOL_BLOCK_TAGS)
    ):
        attrs: dict = open_tag.get("attrs") or {}
        name = attrs.get("name") or attrs.get("function.name") or ""
        args: dict = {}
        if not name:
            child = _parse_raw_child_tags(body)
            name = child.get("name") or ""
            args = {k: v for k, v in child.items() if k not in {"name", "arguments"}}
            raw_args = child.get("arguments")
            if raw_args is not None:
                parsed = _coerce_json_object(raw_args)
                parsed.update(args)
                args = parsed
        else:
            child = _parse_raw_child_tags(body)
            raw_args = child.pop("arguments", None)
            args = child
            if raw_args is not None:
                parsed = _coerce_json_object(raw_args)
                parsed.update(args)
                args = parsed
        raw_args_attr = (
            attrs.get("arguments")
            or attrs.get("args")
            or attrs.get("parameters")
            or attrs.get("json")
        )
        if raw_args_attr is not None:
            parsed = _coerce_json_object(raw_args_attr)
            parsed.update(args)
            args = parsed
        for key, value in attrs.items():
            if key in {"name", "function.name", "arguments", "args", "parameters", "json"}:
                continue
            args.setdefault(key, value)
        if not isinstance(name, str) or not name.strip():
            continue
        name = name.strip()
        canonical_tool_names = {n.lower(): n for n in ctx.workspace.tool_names}
        canonical_name = canonical_tool_names.get(name.lower())
        if canonical_name is None:
            continue
        calls.append(
            {
                "id": f"raw_{idx + 1}",
                "name": canonical_name,
                "arguments": json.dumps(args, ensure_ascii=False),
            }
        )
    return calls


def _contains_raw_tool_markup(text: str) -> bool:
    return bool(_RAW_TOOL_MARKUP_RE.search(text or ""))


def _strip_raw_tool_call_markup(text: str) -> str:
    """Remove raw DSML/XML tool-call blocks and leftover invocation tags."""
    t = text or ""
    blocks = list(_iter_raw_blocks(t, _RAW_TOOL_BLOCK_TAGS))
    for _open_tag, _body, start, end in sorted(
        blocks, key=lambda item: item[2], reverse=True
    ):
        t = t[:start] + " " + t[end:]
    t = re.sub(
        r"<\s*/?\s*(?:｜{1,2}DSML｜{1,2})?\s*(?:tool_calls|invoke|tool_call|"
        r"function_calls?|parameter|param|name|arguments?)\b[^>]*>",
        " ",
        t,
        flags=re.IGNORECASE | re.DOTALL,
    )
    t = re.sub(r"<\s*｜{1,2}DSML｜{1,2}[^>]*>", " ", t, flags=re.IGNORECASE)
    t = _xml_unescape(t)
    return t.strip()




class _ResponsesMiddlewareAdapter:
    """Chat-like response facade for middleware on Responses API runs."""

    def __init__(
        self,
        raw: Any,
        content: str,
        reasoning: str,
        function_calls: list,
        *,
        original_call_ids: set[str] | None = None,
    ):
        self.raw_response = raw
        self._content = content or ""
        self._reasoning_content = reasoning or ""
        self._reasoning = reasoning or ""
        self._tool_calls = [
            _responses_call_to_chat_tool_call(fc) for fc in function_calls
        ]
        if original_call_ids is None:
            original_call_ids = {
                _obj_get(tc, "id", "") or "" for tc in self._tool_calls
            }
        self._original_call_ids = set(original_call_ids)
        self.choices = [
            SimpleNamespace(
                message=SimpleNamespace(
                    role="assistant",
                    content=self._content,
                    reasoning_content=self._reasoning_content,
                    tool_calls=self._tool_calls,
                ),
                finish_reason="tool_calls" if self._tool_calls else "stop",
            )
        ]

    @property
    def content(self) -> str:
        return self._content

    @content.setter
    def content(self, value: str | None) -> None:
        self._content = value or ""
        try:
            self.choices[0].message.content = self._content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning_content(self) -> str:
        return self._reasoning_content

    @reasoning_content.setter
    def reasoning_content(self, value: str | None) -> None:
        self._reasoning_content = value or ""
        try:
            self.choices[0].message.reasoning_content = self._reasoning_content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning(self) -> str:
        return self._reasoning

    @reasoning.setter
    def reasoning(self, value: str | None) -> None:
        self._reasoning = value or ""

    @property
    def tool_calls(self) -> list:
        return self._tool_calls

    @tool_calls.setter
    def tool_calls(self, value: list | None) -> None:
        self._tool_calls = list(value or [])
        try:
            self.choices[0].message.tool_calls = self._tool_calls
            self.choices[0].finish_reason = "tool_calls" if self._tool_calls else "stop"
        except (AttributeError, IndexError, TypeError):
            pass

    def sync_from_message(self) -> None:
        msg = self.choices[0].message
        msg_content = getattr(msg, "content", None)
        if msg_content is not None:
            self._content = msg_content
        elif getattr(self, "content", None) is not None:
            msg.content = self._content
        msg_reasoning = getattr(msg, "reasoning_content", None)
        if msg_reasoning is not None:
            self._reasoning_content = msg_reasoning
            self._reasoning = self._reasoning or msg_reasoning
        msg_tool_calls = getattr(msg, "tool_calls", None)
        self._tool_calls = list(msg_tool_calls or [])
        msg.tool_calls = self._tool_calls

    def common_tool_calls(self) -> list[dict]:
        self.sync_from_message()
        out: list[dict] = []
        for tc in self.tool_calls:
            call_id = _obj_get(tc, "id", "") or ""
            out.append(
                _chat_tool_call_to_common(
                    tc,
                    injected=call_id not in self._original_call_ids,
                )
            )
        return out


def _ensure_responses_adapter(
    response: Any,
    *,
    original_call_ids: set[str],
) -> _ResponsesMiddlewareAdapter:
    """Normalize middleware return values back into the Responses facade."""
    if isinstance(response, _ResponsesMiddlewareAdapter):
        return response

    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        adapter = _ResponsesMiddlewareAdapter(
            response,
            getattr(msg, "content", None) or getattr(response, "content", "") or "",
            getattr(msg, "reasoning_content", None)
            or getattr(response, "reasoning_content", None)
            or getattr(response, "reasoning", None)
            or "",
            [],
            original_call_ids=original_call_ids,
        )
        adapter.choices = choices
        adapter.sync_from_message()
        return adapter

    if getattr(response, "output", None) is not None:
        content, reasoning, function_calls = llm.extract_responses_output(response)
        return _ResponsesMiddlewareAdapter(
            response,
            content,
            reasoning,
            function_calls,
            original_call_ids=original_call_ids,
        )

    adapter = _ResponsesMiddlewareAdapter(
        response,
        getattr(response, "content", None) or "",
        getattr(response, "reasoning_content", None)
        or getattr(response, "reasoning", None)
        or "",
        [],
        original_call_ids=original_call_ids,
    )
    adapter.tool_calls = list(getattr(response, "tool_calls", None) or [])
    return adapter


def _middleware_message_key(msg: Any) -> str:
    try:
        return json.dumps(msg, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        return repr(msg)


def _middleware_additions(before: list, after: list) -> list:
    """Return messages added by before_llm hooks, even if hooks copied lists."""
    remaining: dict[str, int] = {}
    for msg in before:
        key = _middleware_message_key(msg)
        remaining[key] = remaining.get(key, 0) + 1

    added = []
    for msg in after:
        key = _middleware_message_key(msg)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
        else:
            added.append(msg)
    return added


def _responses_input_from_middleware_message(msg: Any) -> dict | None:
    role = _obj_get(msg, "role", "") or ""
    content = _obj_get(msg, "content", "") or ""
    if not content or role not in {"system", "developer", "user", "assistant"}:
        return None
    # Responses API already receives the main system prompt via instructions;
    # runtime middleware nudges are safest as developer messages.
    if role == "system":
        role = "developer"
    return {"role": role, "content": content}


def _middleware_assistant_message(content: str, tc_list: list[dict]) -> dict:
    msg = {"role": "assistant", "content": content or ""}
    if tc_list:
        msg["tool_calls"] = [
            {
                "id": tc["id"],
                "type": "function",
                "function": {
                    "name": tc["name"],
                    "arguments": tc["arguments"],
                },
            }
            for tc in tc_list
        ]
    return msg


async def _dispatch_builtin(name: str, args: dict, ctx: Context) -> str | None:
    """Returns a string result for built-ins; None if `name` is not built-in."""
    if name == "web_search":
        ctx.search_calls += 1
        query = (args.get("query") or "").strip()
        if not query:
            return "web_search requires a non-empty `query`."
        result_text, items = await web_search_structured(query)
        ctx.trace.save_search(ctx.search_calls, query, result_text)
        urls = [item["url"] for item in items]
        ctx.searches.append(
            SearchRecord(
                idx=ctx.search_calls,
                query=query,
                turn=ctx._current_turn,
                items=items,
                urls=urls,
            )
        )
        return result_text

    if name == "read_url":
        ctx.read_calls += 1
        url = (args.get("url") or "").strip()
        focus = (args.get("focus") or "").strip()
        if not url:
            return "read_url requires a non-empty `url`."
        page = await reader.read_url_with_raw(
            url,
            focus or "general relevance",
            extract_prompt=ctx.workspace.extract_prompt,
        )
        extracted = page["extracted"]
        artifact_path = ctx.trace.save_page(
            url, focus, extracted, raw_text=page.get("raw", "")
        )
        success = True
        failure_type = None
        if "[reader] fetch failed" in extracted:
            success, failure_type = False, "fetch_failed"
        elif "[reader] extract error" in extracted:
            success, failure_type = False, "extract_error"
        elif "[reader] no relevant content" in extracted:
            success, failure_type = False, "no_content"
        ctx.reads.append(
            ReadRecord(
                idx=ctx.read_calls,
                url=url,
                focus=focus,
                turn=ctx._current_turn,
                success=success,
                failure_type=failure_type,
                artifact_path=artifact_path,
                content_preview=extracted[:500],
            )
        )
        return extracted

    return None


def _normalize_tool_result(value: Any, ctx: Context, *, tool: str) -> tuple[str, dict]:
    """Normalize custom workspace tool returns into content + metadata."""
    if isinstance(value, ToolResult):
        metadata = value.metadata if isinstance(value.metadata, dict) else {}
        if value.metadata is not metadata:
            ctx.trace.event(
                "tool_result_warning", tool=tool, reason="metadata_not_dict"
            )
        return str(value.content), copy.deepcopy(metadata)
    if isinstance(value, str):
        return value, {}
    if value is None:
        ctx.trace.event("tool_result_warning", tool=tool, reason="none_return")
        return "", {}
    ctx.trace.event(
        "tool_result_warning",
        tool=tool,
        reason=f"unexpected_return_type: {type(value).__name__}",
    )
    return str(value), {}


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)
    return result


