_DSML_TOOL_CALL_RE = re.compile(
    r"<[｜|]{1,2}DSML[｜|]tool_calls>.*?(?:</[｜|]{1,2}DSML[｜|]tool_calls>|\Z)",
    re.IGNORECASE | re.DOTALL,
)
_XML_TAG_RE = re.compile(r"</?[A-Za-z][A-Za-z0-9_:-]*(?:\s[^<>]*)?>", re.DOTALL)
_TOOL_CALL_JSON_RE = re.compile(
    r'\s*\{\s*"name"\s*:\s*"[^"]+"\s*,\s*"arguments"\s*:\s*\{.*?\}\s*\}\s*',
    re.DOTALL,
)
_MARKDOWN_LINK_RE = re.compile(r"\[([^\]]+)\]\([^)]*\)")
_ANSWER_LABEL_RE = re.compile(
    r"^\s*(?:the\s+)?(?:final\s+answer|answer|response|result|conclusion)\s*(?:is|:)?\s*",
    re.IGNORECASE,
)
_LEADING_ARTICLE_LOWERCASE_RE = re.compile(
    r"^\s*(?i:the|a|an)\s+([a-z][a-z\s'’-]*)$"
)
_OUTER_PUNCT_RE = re.compile(
    r"^[\s\"'`‘’“”\-–—:;,.!?*_~|/\\[\](){}<>]+|[\s\"'`‘’“”\-–—:;,.!?*_~|/\\[\](){}<>]+$"
)
_FINAL_ANSWER_GATE_FEEDBACK = (
    "Return only the requested short answer; remove explanations, "
    "parentheticals, alternatives, and titles."
)
_NON_ANSWER_RE = re.compile(
    r"^(?:i\s+don'?t\s+know|not\s+sure|unsure|unknown|no\s+answer|none|n/?a)$",
    re.IGNORECASE,
)
_PERSON_QUESTION_HINT_RE = re.compile(
    r"\b(?:who|whom|whose|person|people|actor|actress|artist|"
    r"author|writer|director|singer|musician|composer|painter|inventor|"
    r"scientist|president|king|queen|leader|founder|ceo|philosopher|poet|"
    r"playwright|politician)\b",
    re.IGNORECASE,
)
_OVERSPECIFIC_SUFFIXES = {
    "river", "rivers", "lake", "lakes", "ocean", "oceans", "sea", "seas",
    "mountain", "mountains", "mount", "island", "islands", "isle",
    "desert", "deserts", "forest", "forests", "jungle", "valley", "valleys",
    "canyon", "canyons", "gorge", "gulf", "gulfs", "bay", "bays",
    "strait", "straits", "channel", "channels", "peninsula", "peninsulas",
    "cape", "plateau", "plateaus", "basin", "basins", "range", "ranges",
    "falls", "glacier", "glaciers", "reef", "reefs", "continent", "continents",
    "country", "countries", "nation", "nations", "city", "cities", "town",
    "towns", "village", "villages", "county", "counties", "province",
    "provinces", "state", "states", "territory", "territories",
    "empire", "empires", "kingdom", "kingdoms", "republic", "republics",
    "dynasty", "dynasties", "company", "companies", "corporation",
    "corporations", "language", "languages", "dialect", "dialects",
    "religion", "religions", "disease", "diseases", "virus", "viruses",
    "bacterium", "bacteria", "syndrome", "syndromes", "disorder",
    "disorders", "cancer", "cancers", "war", "wars", "battle", "battles",
    "revolution", "revolutions", "movement", "movements", "treaty", "treaties",
    "act", "acts", "amendment", "amendments", "theory", "theories", "law",
    "laws", "effect", "effects", "phenomenon", "phenomena", "species",
    "genus", "family", "order", "class", "phylum", "kingdom",
}


def _strip_dsml_and_xml(text: str) -> str:
    """Remove DSML/XML/tool-call markup, including leaked shell-call tags."""
    text = re.sub(_DSML_TOOL_CALL_RE, "", text)
    text = re.sub(r"</?[｜|]{1,2}DSML[｜|][^>]*>", "", text, flags=re.IGNORECASE)
    text = re.sub(_XML_TAG_RE, "", text)
    return text


def _strip_tool_call_json(text: str) -> str:
    """Remove JSON blobs that look like leaked tool-call payloads."""
    prev = None
    while prev != text:
        prev = text
        text = re.sub(_TOOL_CALL_JSON_RE, " ", text)
    return text


def _strip_markdown(text: str) -> str:
    """Remove common Markdown formatting while keeping the underlying text."""
    text = re.sub(r"```(?:[A-Za-z0-9_+-]*)?\s*", "", text)
    text = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", text)
    text = re.sub(_MARKDOWN_LINK_RE, r"\1", text)
    text = re.sub(r"^[ \t]*#{1,6}[ \t]*", "", text, flags=re.MULTILINE)
    text = re.sub(r"^\s*[-*+]\s+", "", text, flags=re.MULTILINE)
    text = re.sub(r"\*\*?|__", "", text)
    return text


def _strip_answer_label(text: str) -> str:
    """Remove leading labels such as 'Answer:' or 'The answer is'."""
    return re.sub(_ANSWER_LABEL_RE, "", text)


def _strip_parentheticals(text: str) -> str:
    """Remove parenthesized/bracketed qualifiers."""
    prev = None
    while prev != text:
        prev = text
        text = re.sub(r"\s*\([^()]*\)", " ", text)
        text = re.sub(r"\s*\[[^\[\]]*\]", " ", text)
        text = text.strip()
    return text


def _strip_outer_punctuation(text: str) -> str:
    """Remove outer punctuation and quote characters."""
    text = text.strip()
    sign = ""
    match = re.match(r"^([-+])(?=\d)", text)
    if match:
        sign = match.group(1)
        text = text[1:]
    text = re.sub(_OUTER_PUNCT_RE, "", text).strip()
    if sign and text and text[0].isdigit():
        text = sign + text
    return text.strip()


def _strip_leading_article_for_lowercase(text: str) -> str:
    """Drop a leading article only when the rest is a lower-case noun phrase."""
    match = _LEADING_ARTICLE_LOWERCASE_RE.match(text)
    if match:
        return match.group(1).strip()
    return text


def _clean_short_answer(text: str) -> str:
    """Clean and canonicalize a model-produced short answer candidate."""
    if not text:
        return ""
    text = _strip_dsml_and_xml(text)
    text = _strip_tool_call_json(text)
    text = _strip_markdown(text)
    text = _strip_answer_label(text)
    text = _strip_parentheticals(text)
    text = _strip_outer_punctuation(text)
    text = _strip_leading_article_for_lowercase(text)
    text = _strip_outer_punctuation(text)
    text = re.sub(r"\s+", " ", text).strip()
    return text


def _safe_clean(text: str) -> str:
    """Clean only the safe, non-semantic parts of a candidate answer.

    This is used to decide whether a cleaned answer can be accepted directly
    without a side-model check. Explanatory parentheticals and alternatives are
    intentionally not stripped here, so they go through the side-model gate.
    """
    text = _strip_markdown(text)
    text = _strip_answer_label(text)
    text = re.sub(
        r"\s*\(\s*(?:c\.?\s*)?\d{1,4}(?:\s*(?:BC|AD|BCE|CE))?\s*\)\s*[.!?]*$",
        "",
        text,
        flags=re.IGNORECASE,
    )
    text = _strip_outer_punctuation(text)
    text = _strip_leading_article_for_lowercase(text)
    text = _strip_outer_punctuation(text)
    return re.sub(r"\s+", " ", text).strip()


def _looks_compact_direct_answer(text: str) -> bool:
    """Return True when *text* is already a minimal direct short answer."""
    if not text or len(text) > 120:
        return False
    if _NON_ANSWER_RE.match(text):
        return False
    if any(ch in text for ch in ("\n", "\r", "\t")):
        return False
    if re.search(r"[*_`]", text) or re.search(r"</?[A-Za-z]", text):
        return False
    if re.search(r"[\(\)\[\]]", text):
        return False
    if "/" in text or "\\" in text:
        return False
    if re.search(r"[!?;]", text):
        return False
    if re.search(r"[.!?;:]\s", text):
        return False
    if re.search(
        r"\b(?:is|are|was|were|be|been|being|refers?\s+to|means?|denotes?|describes?|"
        r"also\s+known\s+as|known\s+as)\b",
        text,
        re.IGNORECASE,
    ):
        return False
    words = re.findall(r"[\wÀ-ÿ'’-]+", text)
    if not 1 <= len(words) <= 8:
        return False
    if len(words) > 3 and not any(w[:1].isupper() or w.isdigit() for w in words):
        return False
    last = re.sub(r"[^A-Za-zÀ-ÿ'-]", "", words[-1]).lower()
    if last in _OVERSPECIFIC_SUFFIXES:
        return False
    return True


def _looks_like_person_name(text: str) -> bool:
    """Return True when *text* looks like a two-word proper-person name."""
    words = re.findall(r"[\wÀ-ÿ'’-]+", text)
    if len(words) != 2:
        return False
    first, second = words
    if not (first[:1].isupper() and second[:1].isupper()):
        return False
    if re.sub(r"[^A-Za-zÀ-ÿ'-]", "", second).lower() in _OVERSPECIFIC_SUFFIXES:
        return False
    return True


_SIDE_FINAL_ANSWER_PROMPT = """\
A model was asked this question:

{question}

It proposed this final answer:

{candidate}

Return only the canonical short answer to the question. Remove explanations,
parentheticals, alternatives, titles, and tool-call markup. Prefer the shortest
unambiguous form; drop redundant category words such as "River", "City", or
"Mountain" only when the shorter name is unambiguous. If the proposed answer is
already the exact minimal direct answer, return it unchanged. If the proposed
answer is off-target or does not answer the question, provide the correct short
answer instead. Do not add punctuation, citations, or commentary."""


def _final_answer_gate_continue(ctx: Context, answer: str) -> tuple[str, str, str | None]:
    """Return a continue action for the loop when the gate is not satisfied."""
    if ctx.remaining_turns <= 0:
        ctx.trace.event("final_answer_gate_continue_rejected", reason="last_turn")
        return "accept", answer, None
    if ctx._final_continues >= ctx._final_continue_max:
        ctx.trace.event(
            "final_answer_gate_continue_rejected",
            reason="budget_exceeded",
            budget=ctx._final_continue_max,
        )
        return "accept", answer, None
    ctx._final_continues += 1
    ctx.trace.event(
        "final_answer_gate_continue",
        count=ctx._final_continues,
        feedback=_FINAL_ANSWER_GATE_FEEDBACK,
    )
    return "continue", answer, _FINAL_ANSWER_GATE_FEEDBACK


def _looks_acceptable_side_answer(text: str) -> bool:
    """Return True when side-model output is a usable short answer."""
    if not text or len(text) > 120:
        return False
    if _NON_ANSWER_RE.match(text):
        return False
    if any(ch in text for ch in ("\n", "\r", "\t")):
        return False
    if re.search(r"[*_`]", text) or re.search(r"</?[A-Za-z]", text):
        return False
    if re.search(r"[\(\)\[\]]", text):
        return False
    if "/" in text or "\\" in text:
        return False
    if re.search(r"[!?;]", text):
        return False
    if re.search(
        r"\b(?:is|are|was|were|be|been|being|refers?\s+to|means?|denotes?|describes?|"
        r"also\s+known\s+as|known\s+as)\b",
        text,
        re.IGNORECASE,
    ):
        return False
    words = re.findall(r"[\wÀ-ÿ'’-]+", text)
    if not 1 <= len(words) <= 8:
        return False
    if len(words) > 3 and not any(w[:1].isupper() or w.isdigit() for w in words):
        return False
    return True


async def _side_canonical_answer(
    original: str, cleaned: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Use the side model to produce a canonical short answer."""
    prompt = _SIDE_FINAL_ANSWER_PROMPT.format(
        question=ctx.question.strip(),
        candidate=(cleaned or original).strip()[:4000],
    )
    side = await ctx.side_text(prompt, purpose="final_answer_gate", max_tokens=120)
    if not side:
        ctx.trace.event("final_answer_gate_side_failed", reason="empty")
        return _final_answer_gate_continue(ctx, cleaned or original.strip())
    side_clean = _clean_short_answer(side)
    if not side_clean:
        ctx.trace.event("final_answer_gate_side_failed", reason="empty_after_clean")
        return _final_answer_gate_continue(ctx, cleaned or original.strip())
    if not _looks_acceptable_side_answer(side_clean):
        ctx.trace.event("final_answer_gate_side_failed", reason="not_canonical")
        return _final_answer_gate_continue(ctx, cleaned or original.strip())
    ctx.trace.event(
        "final_answer_gate_replace",
        before=(cleaned or original.strip())[:160],
        after=side_clean[:160],
    )
    return "accept", side_clean, None


async def _builtin_final_answer_gate(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Validate the no-tool-call completion path's final answer."""
    original = candidate.strip()
    cleaned = _clean_short_answer(candidate)
    ctx.trace.event(
        "final_answer_gate",
        raw_len=len(candidate),
        cleaned_len=len(cleaned),
    )
    if not cleaned:
        return await _side_canonical_answer(original, "", ctx)
    if _looks_compact_direct_answer(cleaned) and _looks_like_person_name(cleaned):
        if not _PERSON_QUESTION_HINT_RE.search(ctx.question):
            return await _side_canonical_answer(original, cleaned, ctx)
    if cleaned == original and _looks_compact_direct_answer(cleaned):
        ctx.trace.event("final_answer_gate_accept", mode="unchanged")
        return "accept", original, None
    if _looks_compact_direct_answer(cleaned) and _safe_clean(original) == cleaned:
        ctx.trace.event("final_answer_gate_accept", mode="cleaned")
        return "accept", cleaned, None
    return await _side_canonical_answer(original, cleaned, ctx)


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)
    return result


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------


async def run(
    question: str,
    *,
    runs_root: Path | str = "runs",
    max_turns: int = 100,
    model: str | None = None,
    workspace_dir: str | Path | None = None,
    editor: bool = False,
    working_dir: str | Path | None = None,
    llm_config: dict | None = None,
    web_config: dict | None = None,
    debug_llm_io: bool = False,
) -> dict[str, Any]:
    llm.configure(llm_config or {})
    web_settings.configure(web_config or {})
    runs_root = Path(runs_root)
    runs_root.mkdir(parents=True, exist_ok=True)
    if editor:
        from .editor import bundle as editor_bundle

        bundle = editor_bundle(Path(workspace_dir))
    else:
        bundle = ws_mod.load(workspace_dir or ws_mod.SEED_WORKSPACE)
        from .web_config import validate_config

        validate_config(bundle.tool_names)
    if working_dir is not None:
        from .editor import attach

        attach(bundle, Path(working_dir))

    model = model or llm.DEFAULT_MODEL
    trace = TraceWriter(
        runs_root, question, config={"llm": llm_config, "web": web_config}
    )
    trace.event(
        "workspace",
        root=str(bundle.root),
        tools=bundle.tool_names,
        middlewares=[m.name for m in bundle.middlewares],
        sub_agents=list(bundle.sub_agents.keys()),
    )
    ctx = Context(
        workspace=bundle,
        trace=trace,
        working_dir=Path(working_dir).resolve() if working_dir else Path.cwd(),
        sub_agents=bundle.sub_agents,
        question=question,
        run_id=trace.dir.name,
        run_dir=str(trace.dir),
        model=model,
        max_turns=max_turns,
    )
    stop_reason = "max_turns"
    answer = ""

    _log_dir = trace.dir / "log" if debug_llm_io else None
    if _log_dir is not None:
        _log_dir.mkdir(exist_ok=True)

    use_responses_api = llm.is_openai_model(model)
    responses_session_id = uuid.uuid4().hex if use_responses_api else None
    llm_config = {
        "model": model,
        "api": "responses" if use_responses_api else "chat_completions",
        "reasoning_effort": llm.REASONING_EFFORT,
        "max_output_tokens": llm.MAX_TOKENS,
        "session_id": responses_session_id,
    }
    trace.event("llm_config", **llm_config)
    response_history: list = []
    responses_tools: list[dict] | None = None
    reasoning_cfg: dict | None = None
    resp_input: list = []
    if use_responses_api:
        responses_tools = llm.chat_tools_to_responses(bundle.tool_schemas)
        reasoning_cfg = (
            {"effort": llm.REASONING_EFFORT} if llm.REASONING_EFFORT else None
        )
        resp_input = [{"role": "user", "content": question}]
        trace.event("responses_api", model=model)

    # Chat Completions sends this message list directly. Responses keeps this
    # view for middleware and replays complete output items for model continuity.
    messages: list[dict] = [
        {"role": "system", "content": bundle.system_prompt},
        {"role": "user", "content": question},
    ]

    last_turn = 0
    for turn in range(1, max_turns + 1):
        last_turn = turn
        ctx._current_turn = turn
        ctx.current_turn_calls = []

        response_input = resp_input
        if use_responses_api:
            before_messages = copy.deepcopy(messages)
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            additions = [
                x
                for m in _middleware_additions(before_messages, messages)
                if (x := _responses_input_from_middleware_message(m)) is not None
            ]
            if additions:
                response_input = resp_input + additions
        else:
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )

        if _log_dir is not None:
            _req_log: dict[str, Any] = {"turn": turn, "model": model}
            if use_responses_api:
                _req_log["type"] = "responses"
                _req_log["input"] = response_history + response_input
                _req_log["continuation"] = "stateless"
                _req_log["session_id"] = responses_session_id
                _req_log["reasoning"] = reasoning_cfg
                _req_log["max_output_tokens"] = llm.MAX_TOKENS
            else:
                _req_log["type"] = "chat"
                _req_log["messages"] = messages
                _req_log["tools_count"] = (
                    len(bundle.tool_schemas) if bundle.tool_schemas else 0
                )
            _req_file = _log_dir / f"turn_{turn:03d}_request.json"
            trace.write_json(_req_file, _req_log)

        is_last_turn = turn == max_turns
        _tc = "none" if is_last_turn else "auto"
        _tools_resp = None if is_last_turn else responses_tools
        _tools_chat = None if is_last_turn else bundle.tool_schemas

        _llm_last_err: Exception | None = None
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    resp = await llm.responses(
                        response_history + response_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=_tools_resp,
                        tool_choice=_tc,
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                else:
                    resp = await llm.chat(
                        messages, model=model, tools=_tools_chat, tool_choice=_tc
                    )

                if _log_dir is not None:
                    try:
                        _resp_data = (
                            resp.model_dump()
                            if hasattr(resp, "model_dump")
                            else repr(resp)
                        )
                    except Exception:
                        _resp_data = repr(resp)
                    _resp_file = _log_dir / f"turn_{turn:03d}_response.json"
                    trace.write_json(_resp_file, {"turn": turn, "response": _resp_data})
                _llm_last_err = None
                break  # success

            except Exception as e:
                _llm_last_err = e
                logger.warning(
                    "LLM call failed (turn %d, attempt %d/%d): %s",
                    turn,
                    _attempt,
                    llm.LLM_MAX_RETRIES,
                    trace.redact(str(e)),
                )
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)  # 2s, 4s

        if _llm_last_err is not None:
            e = _llm_last_err
            http_detail = {}
            for key in ("status_code", "llm_provider", "model"):
                val = getattr(e, key, None)
                if val is not None:
                    http_detail[key] = val
            cur = e
            while cur is not None:
                http_resp = getattr(cur, "response", None)
                if http_resp is not None and hasattr(http_resp, "status_code"):
                    http_detail["status"] = getattr(http_resp, "status_code", None)
                    http_detail["url"] = str(getattr(http_resp, "url", ""))
                    http_detail["headers"] = dict(getattr(http_resp, "headers", {}))
                    try:
                        http_detail["body"] = http_resp.text
                    except Exception:
                        http_detail["body"] = repr(getattr(http_resp, "content", b""))
                    break
                cur = getattr(cur, "original_exception", None) or getattr(
                    cur, "__cause__", None
                )
            logger.warning(
                "LLM call failed (attempts=%d, turn=%d): %s\nHTTP detail: %s",
                _attempt,
                turn,
                trace.redact(str(e)),
                trace.redact(json.dumps(http_detail, ensure_ascii=False, default=str)),
            )
            stop_reason = f"llm_error: {e}"
            break

        usage = {
            "role": "primary",
            "turn": turn,
            "model": model,
            "call_id": getattr(resp, "id", None),
            "latency_seconds": time.monotonic() - request_started,
            "usage": llm.usage_dict(resp),
        }
        ctx.model_usage.append(usage)
        trace.event("model_usage", **usage)
        failure = llm.response_error(resp, responses_api=use_responses_api)
        if failure:
            if use_responses_api:
                partial, _, _ = llm.extract_responses_output(resp)
                messages.append({"role": "assistant", "content": partial})
            elif resp.choices:
                messages.append(_serialize_assistant(resp.choices[0].message))
            stop_reason = f"llm_error: {failure}"
            trace.event("llm_error", turn=turn, error=failure)
            break

        if use_responses_api:
            response_history.extend(copy.deepcopy(response_input))
            response_history.extend(
                item.model_dump(mode="json", exclude_none=True)
                if hasattr(item, "model_dump")
                else copy.deepcopy(item)
                for item in (resp.output or [])
            )
            content, reasoning, function_calls = llm.extract_responses_output(resp)
            adapter = _ResponsesMiddlewareAdapter(
                resp, content, reasoning, function_calls
            )
            original_call_ids = set(adapter._original_call_ids)
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        updated = await mw.after_llm(adapter, ctx)
                        adapter = _ensure_responses_adapter(
                            updated,
                            original_call_ids=original_call_ids,
                        )
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            adapter.sync_from_message()
            content = adapter.content or ""
            reasoning = adapter.reasoning_content or adapter.reasoning or ""
            tc_list = adapter.common_tool_calls()
        else:
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        resp = await mw.after_llm(resp, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )

            # Normalize response into common variables
            tc_list = []
            msg = resp.choices[0].message
            content = msg.content or ""
            reasoning = getattr(msg, "reasoning_content", None) or ""
            for tc in getattr(msg, "tool_calls", None) or []:
                tc_list.append(_chat_tool_call_to_common(tc))

        trace.event(
            "assistant",
            turn=turn,
            content=content,
            reasoning=reasoning,
            n_tool_calls=len(tc_list),
        )

        if not tc_list:
            if not content.strip():
                stop_reason = "llm_error: model returned no final answer text"
                break
            candidate_answer = content
            final_action, final_answer, feedback = await _run_before_final_hooks(
                candidate_answer,
                ctx,
            )
            if final_action == "continue" and feedback:
                messages.append({"role": "assistant", "content": final_answer})
                messages.append({"role": "user", "content": feedback})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": feedback}]
                continue
            gate_action, gate_answer, gate_feedback = await _builtin_final_answer_gate(
                final_answer,
                ctx,
            )
            if gate_action == "continue" and gate_feedback:
                messages.append(
                    {"role": "assistant", "content": gate_answer or final_answer}
                )
                messages.append({"role": "user", "content": gate_feedback})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": gate_feedback}]
                continue
            messages.append({"role": "assistant", "content": gate_answer})
            answer = gate_answer
            stop_reason = "no_tool_calls"
            break

        if use_responses_api:
            messages.append(_middleware_assistant_message(content, tc_list))
        else:
            messages.append(_serialize_assistant(msg))

        tool_outputs: list[dict] = []
        injected_tool_messages: list[dict] = []
        for tc in tc_list:
            name = tc["name"]
            try:
                args = json.loads(tc["arguments"])
            except json.JSONDecodeError:
                args = {}
            before_tool_seq = ctx._tool_seq
            try:
                result = await _dispatch(name, args, ctx)
            except Exception as e:
                result = f"tool error: {e}"
            result_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                result_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=name,
                args=args,
                result=result,
                result_metadata=result_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            if use_responses_api:
                if not tc.get("injected"):
                    tool_outputs.append(
                        {
                            "type": "function_call_output",
                            "call_id": tc["id"],
                            "output": result,
                        }
                    )
                else:
                    injected_tool_messages.append(
                        {
                            "role": "user",
                            "content": (
                                "Runtime middleware executed an additional tool call.\n"
                                f"Tool: {name}\n"
                                f"Arguments: {json.dumps(args, ensure_ascii=False)}\n"
                                f"Result:\n{result}"
                            ),
                        }
                    )
            else:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )
            if use_responses_api:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )

        if use_responses_api:
            resp_input = tool_outputs + injected_tool_messages

        # ── process pending injections from after_tool ──
        if ctx._pending_injections:
            inj = ctx._pending_injections[0]
            inj_name, inj_args = inj["name"], inj.get("args", {})
            ctx._in_injected_call = True
            before_tool_seq = ctx._tool_seq
            try:
                inj_result = await _dispatch(inj_name, inj_args, ctx)
            except Exception as e:
                inj_result = f"injected tool error: {e}"
                trace.event("injection_error", tool=inj_name, error=str(e))
            finally:
                ctx._in_injected_call = False
                ctx._pending_injections.clear()
            inj_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                inj_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=inj_name,
                args=inj_args,
                result=inj_result,
                injected=True,
                result_metadata=inj_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            inj_msg = {
                "role": "user",
                "content": (
                    "Runtime middleware executed an additional tool call.\n"
                    f"Tool: {inj_name}\n"
                    f"Arguments: {json.dumps(inj_args, ensure_ascii=False)}\n"
                    f"Result:\n{inj_result}"
                ),
            }
            if use_responses_api:
                resp_input.append(inj_msg)
            else:
                messages.append(inj_msg)
            ctx._injections_count += 1

    # ------------------------------------------------------------------
    # Strip residual tool-call tokens (e.g. DeepSeek DSML markers)
    # ------------------------------------------------------------------
    def _clean_answer(text: str) -> str:
        return re.sub(
            r"<｜｜DSML｜｜tool_calls>.*?(?:</｜｜DSML｜｜tool_calls>|\Z)",
            "",
            text,
            flags=re.DOTALL,
        ).strip()

    answer = _clean_answer(answer)

    needs_forced_answer = not answer and not stop_reason.startswith("llm_error")

    # ------------------------------------------------------------------
    # Forced answer for non-normal exits
    # ------------------------------------------------------------------
    if needs_forced_answer:
        forced_prompt = (
            "You have used all available turns. No more tool calls are allowed. "
            "Do NOT output any tool-call markup or XML tags. "
            "Provide your best final answer to the original question now "
            "as plain text, citing source URLs inline. "
            "If the evidence you gathered is insufficient, give your best "
            "guess and explicitly note the uncertainty."
        )
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    forced_input = (
                        response_history
                        + resp_input
                        + [{"role": "user", "content": forced_prompt}]
                    )
                    resp = await llm.responses(
                        forced_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=None,
                        tool_choice="none",
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                    forced_content, _, _ = llm.extract_responses_output(resp)
                else:
                    forced_messages = messages + [
                        {"role": "user", "content": forced_prompt}
                    ]
                    resp = await llm.chat(
                        forced_messages, model=model, tools=None, tool_choice="none"
                    )
                    forced_content = (
                        resp.choices[0].message.content if resp.choices else ""
                    )
                usage = {
                    "role": "forced_answer",
                    "turn": last_turn + 1,
                    "model": model,
                    "call_id": getattr(resp, "id", None),
                    "latency_seconds": time.monotonic() - request_started,
                    "usage": llm.usage_dict(resp),
                }
                ctx.model_usage.append(usage)
                trace.event("model_usage", **usage)
                forced = _clean_answer(forced_content or "")
                messages.extend(
                    [
                        {"role": "user", "content": forced_prompt},
                        {"role": "assistant", "content": forced},
                    ]
                )
                failure = llm.response_error(resp, responses_api=use_responses_api)
                if failure:
                    stop_reason = f"llm_error: {failure}"
                    trace.event("llm_error", turn=last_turn + 1, error=failure)
                    break
                if forced:
                    answer = forced
                trace.event(
                    "forced_answer", stop_reason=stop_reason, length=len(forced)
                )
                break
            except Exception as e:
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)

    if not answer:
        answer = "(no answer produced)"
        if not stop_reason.startswith("llm_error"):
            stop_reason = "llm_error: model returned no final answer text"

    if not stop_reason.startswith("llm_error"):
        stop_reason = "completed"

    trace.save_answer(answer)
    summary = {
        "question": question,
        "llm_config": llm_config,
        "stop_reason": stop_reason,
        "turns": last_turn,
        "search_calls": ctx.search_calls,
        "read_calls": ctx.read_calls,
        "run_dir": str(trace.dir),
        "workspace": str(bundle.root),
        "side_llm_calls": ctx._side_llm_calls,
        "unique_urls_searched": len(set(u for sr in ctx.searches for u in sr.urls)),
        "unique_urls_read": len(set(r.url for r in ctx.reads)),
        "read_failures": sum(1 for r in ctx.reads if not r.success),
        "tool_skips": ctx._tool_skips,
        "tool_redirects": ctx._tool_redirects,
        "injections_count": ctx._injections_count,
        "final_continues": ctx._final_continues,
        "usage": ctx.model_usage,
    }
    trace.save_summary(summary)
    trace.event("run_end", **summary)
    trace.close()

    return trace.redact({"answer": answer, "messages": messages, **summary})

