"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import asyncio
import copy
import json
import logging
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


# ---------------------------------------------------------------------------
# Built-in tool dispatch
# ---------------------------------------------------------------------------


def _serialize_assistant(msg) -> dict:
    """Convert an LLM response Message into a plain dict for the next request.

    Preserves `reasoning_content` for models that require it on tool round-trips. Strips
    fields the API rejects on input (`refusal`, `audio`, etc.)."""
    if hasattr(msg, "model_dump"):
        d = msg.model_dump(exclude_none=True)
    elif hasattr(msg, "dict"):
        d = msg.dict(exclude_none=True)
    else:
        d = {"role": getattr(msg, "role", "assistant")}
        if getattr(msg, "content", None) is not None:
            d["content"] = msg.content
        if getattr(msg, "reasoning_content", None) is not None:
            d["reasoning_content"] = msg.reasoning_content
        tcs = getattr(msg, "tool_calls", None)
        if tcs:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": getattr(tc, "type", "function"),
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                for tc in tcs
            ]
    if "tool_calls" in d and "content" not in d:
        d["content"] = ""
    for k in (
        "function_call",
        "audio",
        "annotations",
        "refusal",
        "provider_specific_fields",
    ):
        d.pop(k, None)
    return d


def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _make_chat_tool_call(call_id: str, name: str, arguments: str):
    """Create a chat-completions-shaped tool call object."""
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(name=name, arguments=arguments),
    )


def _responses_call_to_chat_tool_call(fc: Any):
    call_id = (
        _obj_get(fc, "call_id")
        or _obj_get(fc, "id")
        or _obj_get(fc, "tool_call_id")
        or ""
    )
    name = _obj_get(fc, "name") or _obj_get(_obj_get(fc, "function", {}), "name") or ""
    arguments = (
        _obj_get(fc, "arguments")
        or _obj_get(_obj_get(fc, "function", {}), "arguments")
        or "{}"
    )
    if not isinstance(arguments, str):
        arguments = json.dumps(arguments, ensure_ascii=False)
    return _make_chat_tool_call(call_id, name, arguments)


def _chat_tool_call_to_common(tc: Any, *, injected: bool = False) -> dict:
    fn = _obj_get(tc, "function", {}) or {}
    args = _obj_get(fn, "arguments", "{}") or "{}"
    if not isinstance(args, str):
        args = json.dumps(args, ensure_ascii=False)
    out = {
        "id": _obj_get(tc, "id", "") or "",
        "name": _obj_get(fn, "name", "") or "",
        "arguments": args,
    }
    if injected:
        out["injected"] = True
    return out


class _ResponsesMiddlewareAdapter:
    """Chat-like response facade for middleware on Responses API runs."""

    def __init__(
        self,
        raw: Any,
        content: str,
        reasoning: str,
        function_calls: list,
        *,
        original_call_ids: set[str] | None = None,
    ):
        self.raw_response = raw
        self._content = content or ""
        self._reasoning_content = reasoning or ""
        self._reasoning = reasoning or ""
        self._tool_calls = [
            _responses_call_to_chat_tool_call(fc) for fc in function_calls
        ]
        if original_call_ids is None:
            original_call_ids = {
                _obj_get(tc, "id", "") or "" for tc in self._tool_calls
            }
        self._original_call_ids = set(original_call_ids)
        self.choices = [
            SimpleNamespace(
                message=SimpleNamespace(
                    role="assistant",
                    content=self._content,
                    reasoning_content=self._reasoning_content,
                    tool_calls=self._tool_calls,
                ),
                finish_reason="tool_calls" if self._tool_calls else "stop",
            )
        ]

    @property
    def content(self) -> str:
        return self._content

    @content.setter
    def content(self, value: str | None) -> None:
        self._content = value or ""
        try:
            self.choices[0].message.content = self._content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning_content(self) -> str:
        return self._reasoning_content

    @reasoning_content.setter
    def reasoning_content(self, value: str | None) -> None:
        self._reasoning_content = value or ""
        try:
            self.choices[0].message.reasoning_content = self._reasoning_content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning(self) -> str:
        return self._reasoning

    @reasoning.setter
    def reasoning(self, value: str | None) -> None:
        self._reasoning = value or ""

    @property
    def tool_calls(self) -> list:
        return self._tool_calls

    @tool_calls.setter
    def tool_calls(self, value: list | None) -> None:
        self._tool_calls = list(value or [])
        try:
            self.choices[0].message.tool_calls = self._tool_calls
            self.choices[0].finish_reason = "tool_calls" if self._tool_calls else "stop"
        except (AttributeError, IndexError, TypeError):
            pass

    def sync_from_message(self) -> None:
        msg = self.choices[0].message
        msg_content = getattr(msg, "content", None)
        if msg_content is not None:
            self._content = msg_content
        elif getattr(self, "content", None) is not None:
            msg.content = self._content
        msg_reasoning = getattr(msg, "reasoning_content", None)
        if msg_reasoning is not None:
            self._reasoning_content = msg_reasoning
            self._reasoning = self._reasoning or msg_reasoning
        msg_tool_calls = getattr(msg, "tool_calls", None)
        self._tool_calls = list(msg_tool_calls or [])
        msg.tool_calls = self._tool_calls

    def common_tool_calls(self) -> list[dict]:
        self.sync_from_message()
        out: list[dict] = []
        for tc in self.tool_calls:
            call_id = _obj_get(tc, "id", "") or ""
            out.append(
                _chat_tool_call_to_common(
                    tc,
                    injected=call_id not in self._original_call_ids,
                )
            )
        return out


def _ensure_responses_adapter(
    response: Any,
    *,
    original_call_ids: set[str],
) -> _ResponsesMiddlewareAdapter:
    """Normalize middleware return values back into the Responses facade."""
    if isinstance(response, _ResponsesMiddlewareAdapter):
        return response

    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        adapter = _ResponsesMiddlewareAdapter(
            response,
            getattr(msg, "content", None) or getattr(response, "content", "") or "",
            getattr(msg, "reasoning_content", None)
            or getattr(response, "reasoning_content", None)
            or getattr(response, "reasoning", None)
            or "",
            [],
            original_call_ids=original_call_ids,
        )
        adapter.choices = choices
        adapter.sync_from_message()
        return adapter

    if getattr(response, "output", None) is not None:
        content, reasoning, function_calls = llm.extract_responses_output(response)
        return _ResponsesMiddlewareAdapter(
            response,
            content,
            reasoning,
            function_calls,
            original_call_ids=original_call_ids,
        )

    adapter = _ResponsesMiddlewareAdapter(
        response,
        getattr(response, "content", None) or "",
        getattr(response, "reasoning_content", None)
        or getattr(response, "reasoning", None)
        or "",
        [],
        original_call_ids=original_call_ids,
    )
    adapter.tool_calls = list(getattr(response, "tool_calls", None) or [])
    return adapter


def _middleware_message_key(msg: Any) -> str:
    try:
        return json.dumps(msg, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        return repr(msg)


def _middleware_additions(before: list, after: list) -> list:
    """Return messages added by before_llm hooks, even if hooks copied lists."""
    remaining: dict[str, int] = {}
    for msg in before:
        key = _middleware_message_key(msg)
        remaining[key] = remaining.get(key, 0) + 1

    added = []
    for msg in after:
        key = _middleware_message_key(msg)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
        else:
            added.append(msg)
    return added


def _responses_input_from_middleware_message(msg: Any) -> dict | None:
    role = _obj_get(msg, "role", "") or ""
    content = _obj_get(msg, "content", "") or ""
    if not content or role not in {"system", "developer", "user", "assistant"}:
        return None
    # Responses API already receives the main system prompt via instructions;
    # runtime middleware nudges are safest as developer messages.
    if role == "system":
        role = "developer"
    return {"role": role, "content": content}


def _middleware_assistant_message(content: str, tc_list: list[dict]) -> dict:
    msg = {"role": "assistant", "content": content or ""}
    if tc_list:
        msg["tool_calls"] = [
            {
                "id": tc["id"],
                "type": "function",
                "function": {
                    "name": tc["name"],
                    "arguments": tc["arguments"],
                },
            }
            for tc in tc_list
        ]
    return msg


async def _dispatch_builtin(name: str, args: dict, ctx: Context) -> str | None:
    """Returns a string result for built-ins; None if `name` is not built-in."""
    if name == "web_search":
        ctx.search_calls += 1
        query = (args.get("query") or "").strip()
        if not query:
            return "web_search requires a non-empty `query`."
        result_text, items = await web_search_structured(query)
        ctx.trace.save_search(ctx.search_calls, query, result_text)
        urls = [item["url"] for item in items]
        ctx.searches.append(
            SearchRecord(
                idx=ctx.search_calls,
                query=query,
                turn=ctx._current_turn,
                items=items,
                urls=urls,
            )
        )
        return result_text

    if name == "read_url":
        ctx.read_calls += 1
        url = (args.get("url") or "").strip()
        focus = (args.get("focus") or "").strip()
        if not url:
            return "read_url requires a non-empty `url`."
        page = await reader.read_url_with_raw(
            url,
            focus or "general relevance",
            extract_prompt=ctx.workspace.extract_prompt,
        )
        extracted = page["extracted"]
        artifact_path = ctx.trace.save_page(
            url, focus, extracted, raw_text=page.get("raw", "")
        )
        success = True
        failure_type = None
        if "[reader] fetch failed" in extracted:
            success, failure_type = False, "fetch_failed"
        elif "[reader] extract error" in extracted:
            success, failure_type = False, "extract_error"
        elif "[reader] no relevant content" in extracted:
            success, failure_type = False, "no_content"
        ctx.reads.append(
            ReadRecord(
                idx=ctx.read_calls,
                url=url,
                focus=focus,
                turn=ctx._current_turn,
                success=success,
                failure_type=failure_type,
                artifact_path=artifact_path,
                content_preview=extracted[:500],
            )
        )
        return extracted

    return None


def _normalize_tool_result(value: Any, ctx: Context, *, tool: str) -> tuple[str, dict]:
    """Normalize custom workspace tool returns into content + metadata."""
    if isinstance(value, ToolResult):
        metadata = value.metadata if isinstance(value.metadata, dict) else {}
        if value.metadata is not metadata:
            ctx.trace.event(
                "tool_result_warning", tool=tool, reason="metadata_not_dict"
            )
        return str(value.content), copy.deepcopy(metadata)
    if isinstance(value, str):
        return value, {}
    if value is None:
        ctx.trace.event("tool_result_warning", tool=tool, reason="none_return")
        return "", {}
    ctx.trace.event(
        "tool_result_warning",
        tool=tool,
        reason=f"unexpected_return_type: {type(value).__name__}",
    )
    return str(value), {}


# ---------------------------------------------------------------------------
# Tool observations shown to the LLM
# ---------------------------------------------------------------------------

MAX_TOOL_OBSERVATION_CHARS = 32000
_TOOL_OBSERVATION_TRUNCATION_MARKER = "[tool output truncated]"
_TOOL_WINDOW_MAX_CHARS = 1200
_TOOL_WINDOW_SCORE_THRESHOLD = 0.30
_TOOL_WINDOW_SCORE_RATIO = 0.12
_TOOL_ENTITY_IGNORE = {
    "title", "url", "snippet", "search", "results", "http", "https",
    "www", "com", "org", "html", "htm", "page", "source",
}
_TOOL_STOPWORDS = {
    "a", "an", "the", "of", "in", "on", "at", "to", "for", "from",
    "by", "with", "without", "about", "and", "or", "but", "is", "are",
    "was", "were", "be", "been", "being", "am", "do", "does", "did",
    "doing", "have", "has", "had", "having", "it", "its", "this",
    "that", "these", "those", "as", "than", "then", "also", "which",
    "what", "who", "whom", "whose", "where", "when", "why", "how",
    "if", "can", "could", "should", "would", "will", "shall", "may",
    "might", "must", "not", "no", "yes", "their", "there", "they",
    "them", "his", "her", "hers", "he", "she", "we", "you", "your",
    "yours", "our", "ours", "my", "mine", "me", "us", "i", "s", "t",
}
_TOOL_ANSWER_CUE_RE = re.compile(
    r"\b(?:is|was|are|were|has|have|had|means|refers to|known as|known for|"
    r"located in|situated in|home to|capital of|founded in|born in|"
    r"died in|buried in|named after|also known as|graduated from|"
    r"earned|received|awarded|degree|bachelor|master|doctorate|"
    r"moved to|relocated to|settled in)\b",
    re.IGNORECASE,
)
_TOOL_QUOTED_RE = re.compile(r'"[^"\n]{2,}"')
_TOOL_NUMBER_RE = re.compile(r"\b(?:\d{1,3}(?:,\d{3})+|\d{3,})\b")


def _truncate_tool_observation(text: str, max_chars: int) -> tuple[str, bool]:
    """Cap tool output and mark the truncation explicitly."""
    if len(text) <= max_chars:
        return text, False
    return (
        text[:max_chars].rstrip() + "\n" + _TOOL_OBSERVATION_TRUNCATION_MARKER,
        True,
    )


def _tokens_for_overlap(text: str) -> list[str]:
    return re.findall(r"[a-z0-9]+", text.lower())


def _bigrams(tokens: list[str]) -> set[tuple[str, str]]:
    return set(zip(tokens, tokens[1:]))


def _question_overlap_signals(
    question: str,
) -> tuple[set[str], set[tuple[str, str]], list[str]]:
    tokens = [t for t in _tokens_for_overlap(question) if t not in _TOOL_STOPWORDS]
    phrases = [
        p.strip().lower()
        for p in re.findall(r'"([^"]+)"', question)
        if p.strip()
    ]
    return set(tokens), _bigrams(tokens), phrases


def _split_long_block(block: str) -> list[str]:
    """Split a long block on sentence boundaries, then newlines, then words."""
    out: list[str] = []
    for piece in re.split(r"(?<=[.!?])\s+(?=[A-Z0-9'\"([*])", block):
        piece = piece.strip()
        if not piece:
            continue
        if len(piece) <= _TOOL_WINDOW_MAX_CHARS:
            out.append(piece)
            continue
        for line in re.split(r"\n+", piece):
            line = line.strip()
            if not line:
                continue
            if len(line) <= _TOOL_WINDOW_MAX_CHARS:
                out.append(line)
                continue
            out.extend(_wrap_long_line(line))
    return out


def _wrap_long_line(line: str) -> list[str]:
    out: list[str] = []
    while len(line) > _TOOL_WINDOW_MAX_CHARS:
        cut = line.rfind(" ", 0, _TOOL_WINDOW_MAX_CHARS)
        if cut <= 0:
            cut = _TOOL_WINDOW_MAX_CHARS
        out.append(line[:cut].rstrip())
        line = line[cut:].lstrip()
    if line.strip():
        out.append(line.strip())
    return out


def _windows_from_text(text: str) -> list[str]:
    """Split tool output into complete sentence/paragraph-style windows."""
    normalized = text.replace("\r\n", "\n").replace("\r", "\n")
    blocks = [b.strip() for b in re.split(r"\n\s*\n", normalized) if b.strip()]
    windows: list[str] = []
    for block in blocks:
        if len(block) <= _TOOL_WINDOW_MAX_CHARS and "\n" in block:
            # Search-result/list style blocks are most useful as a unit.
            windows.append(block)
        elif len(block) <= _TOOL_WINDOW_MAX_CHARS:
            # Prose paragraphs are split into sentence windows so a single
            # answer-bearing sentence is not tied to surrounding filler.
            windows.extend(_split_long_block(block))
        else:
            windows.extend(_split_long_block(block))
    return windows


def _named_entity_signal(text: str) -> float:
    """Weak answer-span signal from title-case names (not all-caps headers)."""
    words = re.findall(r"[A-Za-z][A-Za-z0-9'\-]*", text)
    score = 0.0
    for i, word in enumerate(words):
        lowered = word.lower()
        if lowered in _TOOL_ENTITY_IGNORE or lowered in _TOOL_STOPWORDS:
            continue
        if word.isupper():
            # ALL-CAPS is usually a heading/emphasis, not an answer entity.
            score += 0.05
            continue
        if not word[0].isupper() or len(word) == 1:
            continue
        if i == 0:
            # A single leading title-case word is often a standalone answer
            # (e.g. "Sahara" or "Superior"); ordinary sentence starters in
            # longer windows are too noisy to use as entity evidence.
            if len(words) == 1:
                score += 0.30
            continue
        prev = words[i - 1]
        if prev and prev[-1] in ".!?":
            continue
        score += 0.30
    return score


def _answer_like_signal(text: str) -> float:
    score = 0.0
    if _TOOL_ANSWER_CUE_RE.search(text):
        score += 0.50
    score += 0.20 * min(len(_TOOL_NUMBER_RE.findall(text)), 4)
    if _TOOL_QUOTED_RE.search(text):
        score += 0.60
    return score


def _strong_answer_span(window: str) -> bool:
    """Heuristic for windows that look like they carry an answer themselves."""
    return (
        _named_entity_signal(window) >= 0.3
        and _answer_like_signal(window) >= 0.4
    ) or _named_entity_signal(window) >= 0.9


def _score_window(
    window: str,
    question_tokens: set[str],
    question_bigrams: set[tuple[str, str]],
    question_phrases: list[str],
) -> float:
    lower = window.lower()
    tokens = [t for t in _tokens_for_overlap(window) if t not in _TOOL_STOPWORDS]
    token_set = set(tokens)

    score = 0.0
    if question_tokens:
        score += float(sum(1.0 for t in question_tokens if t in token_set))
    if question_phrases:
        score += float(sum(2.0 for phrase in question_phrases if phrase in lower))
    if question_bigrams:
        score += 1.5 * len(question_bigrams & _bigrams(tokens))
    score += min(_named_entity_signal(window), 1.5)
    score += _answer_like_signal(window)
    return score


def _truncate_at_sentence_boundary(text: str, max_chars: int) -> tuple[str, bool]:
    """Cap long text at the last sentence boundary with a truncation marker."""
    if len(text) <= max_chars:
        return text, False
    prefix = text[:max_chars]
    boundary: int | None = None
    for match in re.finditer(r"[.!?](?:\s+|$)", prefix):
        boundary = match.end()
    if boundary:
        cut = boundary
    else:
        cut = max(prefix.rfind("\n"), prefix.rfind(" "))
        if cut <= 0:
            cut = max_chars
    truncated = prefix[:cut].rstrip()
    return (
        truncated + "\n" + _TOOL_OBSERVATION_TRUNCATION_MARKER,
        True,
    )


def _content_aware_window_selection(
    text: str, question: str, max_chars: int
) -> tuple[str, bool]:
    """Keep complete high-overlap windows and cap only at sentence boundaries."""
    windows = _windows_from_text(text)
    if len(windows) <= 1:
        return _truncate_at_sentence_boundary(text, max_chars)

    question_tokens, question_bigrams, question_phrases = _question_overlap_signals(
        question
    )
    if not question_tokens and not question_bigrams and not question_phrases:
        return _truncate_at_sentence_boundary(text, max_chars)

    scored: list[tuple[float, int, str]] = []
    for index, window in enumerate(windows):
        scored.append(
            (
                _score_window(
                    window,
                    question_tokens,
                    question_bigrams,
                    question_phrases,
                ),
                index,
                window,
            )
        )

    positive = [(s, i, w) for s, i, w in scored if s > 0.0]
    if not positive:
        return _truncate_at_sentence_boundary(text, max_chars)

    max_score = max(s for s, _, _ in scored)
    threshold = max(_TOOL_WINDOW_SCORE_THRESHOLD, _TOOL_WINDOW_SCORE_RATIO * max_score)
    kept = [
        (s, i, w)
        for s, i, w in positive
        if s >= threshold or _strong_answer_span(w)
    ]
    if not kept:
        kept = positive

    # Fill the budget with complete windows, best-scoring first, then restore
    # the original reading order. Lower-scoring complete windows are discarded
    # before any character-level truncation is attempted.
    ranked = sorted(
        kept,
        key=lambda item: (
            0 if _strong_answer_span(item[2]) else 1,
            -item[0],
            item[1],
        ),
    )
    selected: list[tuple[int, str]] = []
    selected_signatures: list[set[str]] = []
    used = 0
    capped = False
    for score, index, window in ranked:
        window_tokens = set(_tokens_for_overlap(window))
        duplicate = False
        for signature in selected_signatures:
            union = len(window_tokens | signature)
            if union and len(window_tokens & signature) / union >= 0.85:
                duplicate = True
                break
        if duplicate:
            continue
        if not selected and len(window) > max_chars:
            return _truncate_at_sentence_boundary(window, max_chars)
        separator = 2 if selected else 0
        if selected and used + separator + len(window) > max_chars:
            capped = True
            break
        selected.append((index, window))
        selected_signatures.append(window_tokens)
        used += separator + len(window)

    selected.sort(key=lambda item: item[0])
    output = "\n\n".join(window for _, window in selected).strip()
    if capped:
        output += "\n" + _TOOL_OBSERVATION_TRUNCATION_MARKER
    return output, capped


def format_tool_observation(
    result: Any,
    *,
    max_chars: int = MAX_TOOL_OBSERVATION_CHARS,
    question: str = "",
) -> str:
    """Build the concise tool observation that enters the LLM context.

    The full raw result is recorded separately in traces and
    ``ctx.tool_history``; this function is intentionally lossy and only
    controls what the model sees next. Shell-style JSON results are parsed so
    the model receives just ``output`` plus non-default status signals. When a
    question is supplied, output is split into complete sentence/segment
    windows, scored by overlap with the question plus named-entity and
    answer-like span signals, and only the highest-scoring complete windows are
    retained before the length cap is applied at sentence boundaries.
    """
    if result is None:
        return "[tool produced no output]"
    text = result if isinstance(result, str) else str(result)
    text = text.strip()
    if not text:
        return "[tool produced no output]"

    parsed: dict | None = None
    if text.startswith("{"):
        try:
            candidate = json.loads(text)
            if isinstance(candidate, dict) and isinstance(
                candidate.get("output"), str
            ):
                parsed = candidate
        except (json.JSONDecodeError, TypeError):
            parsed = None

    tool_truncated = False
    if parsed is not None:
        if parsed.get("timed_out"):
            return "[tool failed: timed out]"
        exit_code = parsed.get("exit_code")
        if exit_code not in (0, None):
            return f"[tool failed: exit code {exit_code}]"
        output = parsed["output"].strip()
        if not output:
            return "[tool produced no output]"
        text = output
        tool_truncated = bool(parsed.get("truncated"))

    question = (question or "").strip()
    if question and len(text) > 1:
        text, capped = _content_aware_window_selection(text, question, max_chars)
    else:
        text, capped = _truncate_at_sentence_boundary(text, max_chars)

    if tool_truncated and not capped:
        text = text.rstrip() + "\n" + _TOOL_OBSERVATION_TRUNCATION_MARKER
    return text


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)
    return result


